import numpy as np
import pandas as pd
import xarray as xr
from xarray.core.missing import get_clean_interp_index

caught=[]

def tracer(frame, event, arg):
    if event == 'exception' and frame.f_code.co_name == 'get_clean_interp_index':
        exc_type, exc, tb = arg
        name = exc_type.__name__
        if name not in caught:
            caught.append(name)
    return tracer

arr_multi = xr.DataArray(
    np.array([1.0, 2.0, 3.0, 4.0], dtype=np.float64),
    dims=("m",),
    coords={"m": pd.MultiIndex.from_product([["g1", "g2"], [0, 1]], names=["grp", "pos"])}
)
arr_str = xr.DataArray(
    np.array([10.0, 20.0, 30.0], dtype=np.float64),
    dims=("x",),
    coords={"x": np.array(["s0", "s1", "s2"], dtype=object)}
)

import sys
sys.settrace(tracer)
for arr, dim in [(arr_multi, 'm'), (arr_str, 'x')]:
    try:
        get_clean_interp_index(arr, dim, use_coordinate=True, strict=False)
    except Exception:
        pass
sys.settrace(None)
print(caught)
